const reply = $json.response || $json.output || "Thanks for contacting NaijaMart. How else can I help?";
const knownOutcomeStatuses = new Set([
  "NEEDS_CLARIFICATION", "NOT_FOUND", "OUT_OF_STOCK", "PRODUCT_NOT_FOUND",
  "ORDER_NOT_PLACED", "NEEDS_QUANTITY", "INVALID_QUANTITY", "ORDER_NOT_FOUND",
  "GREETING"
]);
const sourceStatus = String($json.status || "");
const auditStatus = $json.escalation_required === true
  ? "ESCALATED"
  : (knownOutcomeStatuses.has(sourceStatus) ? sourceStatus : "COMPLETED");
const intent = String($("Parse Ai Response").first().json.ai?.intent || "UNKNOWN");
const startedAt = Date.parse($("Normalize input").first().json.received_at || "");
const durationMs = Number.isFinite(startedAt) ? Math.max(0, Date.now() - startedAt) : null;
return {json:{...$json,response:reply,output:reply,audit_status:auditStatus,audit_action:`${intent}:${auditStatus}`,duration_ms:durationMs}};

const original = $("Finalize Customer Response").first().json;
const logWritten = $json.audit_log_written === true;
return {json:{
  ...original,
  audit_log_written: logWritten,
  audit_log_id: $json.audit_log_id ?? null,
  audit_log_warning: logWritten ? null : "Customer response returned, but the audit log write may have failed. Check the Log Activity node execution."
}};
